// Preview follows effective placement overrides without reading application state.
export function previewCampaign({placements=[],campaigns=[],zoneId,device='desktop'}){
 const relevant=placements.filter(p=>!p.device||p.device===device);
 const placement=relevant.find(p=>p.id===zoneId);
 if(placement?.enabled===false)return null;
 const ids=Array.isArray(placement?.campaignIds)?placement.campaignIds:[];
 const suitable=c=>{const fields=c.draft||c.live||c;return !Array.isArray(fields.devices)||fields.devices.includes(device);};
 if(ids.length)return campaigns.find(c=>ids.includes(c.id)&&suitable(c))||null;
 return campaigns.find(c=>{const fields=c.draft||c.live||c;return suitable(c)&&fields.placement===zoneId&&!relevant.some(p=>p.id!==zoneId&&p.enabled!==false&&p.campaignIds?.includes(c.id));})||null;
}
